-- 435 IC Engines
(435,'govt_basic','ice-concept','concept',1,'IC इंजन',$j${"note":"परीक्षा में पेट्रोल बनाम डीज़ल इंजन का फर्क (spark plug बनाम संपीड़न) सबसे ज़्यादा पूछा जाता है।","text":"IC इंजन के अंदर ईंधन जलता है। पेट्रोल इंजन में चिंगारी से और डीज़ल इंजन में संपीड़न से ईंधन जलता है। 2-स्ट्रोक और 4-स्ट्रोक मुख्य प्रकार हैं।"}$j$::jsonb,'hi'),
(435,'govt_technical','ice-concept','concept',1,'IC इंजन — SSC JE / RRB JE',$j${"note":"पेट्रोल में spark plug से ईंधन जलता है, डीज़ल में संपीड़न से गर्म हुई हवा से (compression ignition)।","text":"पेट्रोल इंजन Otto चक्र और डीज़ल इंजन Diesel चक्र पर चलता है। 4-स्ट्रोक इंजन में हर दो घूर्णन पर एक power stroke होता है, 2-स्ट्रोक में हर घूर्णन पर।"}$j$::jsonb,'hi'),
(435,'govt_basic','ice-formula','formula',2,'संपीड़न अनुपात',$j${"formula":"r = V₁ / V₂","explanation":"r = संपीड़न अनुपात, V₁ = कुल सिलेंडर आयतन, V₂ = क्लीयरेंस आयतन"}$j$::jsonb,'hi'),
(435,'govt_technical','ice-formula','formula',2,'Otto चक्र की दक्षता',$j${"formula":"η = 1 − 1 / r^(γ−1)","explanation":"r = संपीड़न अनुपात, γ = 1.4 (हवा के लिए), η = दक्षता · r बढ़ने पर दक्षता बढ़ती है"}$j$::jsonb,'hi'),
(435,'govt_basic','ice-example','example',3,'उदाहरण',$j${"answer":"8","question":"कुल आयतन 400 cm³ और क्लीयरेंस आयतन 50 cm³ है। संपीड़न अनुपात कितना है?","solution":"r = 400 / 50 = 8"}$j$::jsonb,'hi'),
(435,'govt_technical','ice-example','example',3,'Numerical (JE style)',$j${"answer":"लगभग 56.5%","question":"संपीड़न अनुपात 8 और γ = 1.4 वाले Otto चक्र की दक्षता कितनी है?","solution":"η = 1 − 1/8^0.4 = 1 − 1/2.297 ≈ 0.565"}$j$::jsonb,'hi'),
(435,'govt_basic','ice-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"पेट्रोल इंजन में ईंधन जलाने के लिए क्या लगाया जाता है?","answer":0,"options":["Spark plug","Radiator","Piston","Fuel tank"],"explanation":"पेट्रोल इंजन में spark plug से चिंगारी देकर ईंधन जलाया जाता है।"},{"q":"4-स्ट्रोक इंजन में कितने स्ट्रोक होते हैं?","answer":2,"options":["2","3","4","6"],"explanation":"सेवन, संपीड़न, कार्य और निकास, चार स्ट्रोक होते हैं।"}]}$j$::jsonb,'hi'),
(435,'govt_technical','ice-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"डीज़ल इंजन में ईंधन कैसे जलता है?","answer":1,"options":["Spark plug से","संपीड़न से गर्म हुई हवा से (compression ignition)","चिंगारी से","उत्प्रेरक से"],"explanation":"डीज़ल इंजन में हवा को इतना संपीड़ित किया जाता है कि ईंधन अपने-आप जल उठता है।"},{"q":"4-स्ट्रोक इंजन में एक power stroke कितने घूर्णन पर होता है?","answer":1,"options":["एक","दो","तीन","चार"],"explanation":"4-स्ट्रोक इंजन में चार स्ट्रोक दो घूर्णन में पूरे होते हैं, जिनमें एक power stroke है।"}]}$j$::jsonb,'hi'),
(435,null,'ice-diagram','svg',5,'पिस्टन और सिलेंडर',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='100' y='15' width='100' height='90' fill='none' stroke='#64748b' stroke-width='3'/><rect x='110' y='55' width='80' height='20' fill='#60a5fa'/><line x1='150' y1='75' x2='150' y2='105' stroke='#14b8a6' stroke-width='4'/><text x='150' y='12' text-anchor='middle' fill='#64748b' font-size='11'>सिलेंडर और पिस्टन</text></svg>","caption":"पिस्टन सिलेंडर में ऊपर-नीचे चलकर ईंधन की ऊर्जा को यांत्रिक कार्य में बदलता है"}$j$::jsonb,'hi'),
-- 436 Production Engineering
(436,'govt_basic','prod-concept','concept',1,'उत्पादन प्रक्रिया',$j${"note":"परीक्षा में ढलाई और फोर्जिंग के उदाहरण पूछे जाते हैं।","text":"धातु को आकार देने के तरीके: ढलाई (पिघली धातु साँचे में), फोर्जिंग (हथौड़े या दबाव से), रोलिंग (रोलर से दबाकर) और वेल्डिंग (जोड़ना)।"}$j$::jsonb,'hi'),
(436,'govt_technical','prod-concept','concept',1,'उत्पादन प्रक्रियाएँ — SSC JE / RRB JE',$j${"note":"JE में कास्टिंग (ढलाई) और फोर्जिंग (दबाव से आकार) का फर्क अक्सर पूछा जाता है।","text":"धातु को आकार देने की मुख्य प्रक्रियाएँ कास्टिंग (ढलाई), फोर्जिंग, रोलिंग, वेल्डिंग और मशीनिंग हैं। कास्टिंग में पिघली धातु साँचे में डाली जाती है, जिससे जटिल आकार बनते हैं।"}$j$::jsonb,'hi'),
(436,'govt_basic','prod-formula','formula',2,'टूल जीवन',$j${"formula":"V · Tⁿ = C","explanation":"V = कटिंग गति, T = टूल जीवन, n और C = स्थिरांक"}$j$::jsonb,'hi'),
(436,'govt_technical','prod-formula','formula',2,'टूल जीवन का Taylor समीकरण',$j${"formula":"V · Tⁿ = C","explanation":"V = कटिंग गति (m/min), T = टूल जीवन (min), n और C = प्रयोग से मिले स्थिरांक"}$j$::jsonb,'hi'),
(436,'govt_basic','prod-example','example',3,'उदाहरण',$j${"answer":"16 min","question":"Taylor समीकरण में n = 0.5 और C = 200 है। कटिंग गति 50 m/min हो तो टूल जीवन कितना होगा?","solution":"50 × T^0.5 = 200 ⇒ T^0.5 = 4 ⇒ T = 16"}$j$::jsonb,'hi'),
(436,'govt_technical','prod-example','example',3,'Numerical (JE style)',$j${"answer":"4 min","question":"Taylor के समीकरण में n = 0.5 और C = 200 है। कटिंग गति 100 m/min हो तो टूल जीवन कितना होगा?","solution":"100 × T^0.5 = 200 ⇒ T^0.5 = 2 ⇒ T = 4"}$j$::jsonb,'hi'),
(436,'govt_basic','prod-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"धातु को जोड़ने की प्रक्रिया कौन सी है?","answer":0,"options":["वेल्डिंग","फोर्जिंग","रोलिंग","कास्टिंग"],"explanation":"वेल्डिंग दो धातु के टुकड़ों को गर्मी या दबाव से जोड़ने की प्रक्रिया है।"},{"q":"रोलर से दबाकर धातु की चादर बनाने की प्रक्रिया क्या है?","answer":0,"options":["रोलिंग","ढलाई","ड्रिलिंग","फोर्जिंग"],"explanation":"रोलिंग में धातु को दो घूमते रोलरों के बीच से गुजारकर पतला किया जाता है।"}]}$j$::jsonb,'hi'),
(436,'govt_technical','prod-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"दबाव से धातु को आकार देने की प्रक्रिया कौन सी है?","answer":0,"options":["फोर्जिंग","कास्टिंग","वेल्डिंग","ड्रिलिंग"],"explanation":"फोर्जिंग में धातु को हथौड़े या दबाव से आकार दिया जाता है।"},{"q":"पिघली धातु साँचे में डालकर आकार देने की प्रक्रिया कौन सी है?","answer":1,"options":["फोर्जिंग","ढलाई (Casting)","रोलिंग","वेल्डिंग"],"explanation":"ढलाई (casting) में पिघली धातु को साँचे में डालकर ठंडा किया जाता है।"}]}$j$::jsonb,'hi'),
(436,null,'prod-diagram','svg',5,'कास्टिंग का साँचा',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='90' y='30' width='120' height='70' fill='none' stroke='#64748b' stroke-width='3'/><rect x='110' y='50' width='80' height='30' fill='#f59e0b' opacity='0.7'/><line x1='150' y1='10' x2='150' y2='30' stroke='#14b8a6' stroke-width='4'/><polygon points='150,30 145,20 155,20' fill='#14b8a6'/><text x='150' y='115' text-anchor='middle' fill='#64748b' font-size='11'>पिघली धातु साँचे में</text></svg>","caption":"ढलाई में पिघली धातु साँचे में भरकर ठंडी होने दी जाती है"}$j$::jsonb,'hi'),
-- 437 Refrigeration & AC
(437,'govt_basic','ref-concept','concept',1,'रेफ्रिजरेशन',$j${"note":"परीक्षा में कंप्रेसर (दाब बढ़ाने वाला) और इवैपोरेटर (ठंडक देने वाला) का फर्क पूछा जाता है।","text":"रेफ्रिजरेटर अंदर की ऊष्मा बाहर निकालकर ठंडक बनाए रखता है। मुख्य भाग कंप्रेसर, कंडेन्सर, एक्सपैंशन वाल्व और इवैपोरेटर हैं।"}$j$::jsonb,'hi'),
(437,'govt_technical','ref-concept','concept',1,'रेफ्रिजरेशन — SSC JE / RRB JE',$j${"note":"JE में चक्र के चारों भाग और COP का सूत्र अक्सर पूछा जाता है।","text":"रेफ्रिजरेशन में ऊष्मा को कम तापमान से अधिक तापमान की ओर ले जाया जाता है। वाष्प-संपीड़न चक्र में कंप्रेसर, कंडेन्सर, एक्सपैंशन वाल्व और इवैपोरेटर होते हैं।"}$j$::jsonb,'hi'),
(437,'govt_basic','ref-formula','formula',2,'COP',$j${"formula":"COP = Q_L / W","explanation":"COP = निष्पादन गुणांक, Q_L = शीतलन प्रभाव, W = कार्य इनपुट"}$j$::jsonb,'hi'),
(437,'govt_technical','ref-formula','formula',2,'निष्पादन गुणांक (COP)',$j${"formula":"COP = Q_L / W","explanation":"Q_L = निम्न तापमान से निकाली गई ऊष्मा (kJ), W = कंप्रेसर को दिया कार्य (kJ) · COP 1 से अधिक हो सकता है"}$j$::jsonb,'hi'),
(437,'govt_basic','ref-example','example',3,'उदाहरण',$j${"answer":"2","question":"एक रेफ्रिजरेटर 200 kJ ऊष्मा निकालता है और उसे 100 kJ कार्य देना पड़ता है। COP कितना है?","solution":"COP = 200 / 100 = 2"}$j$::jsonb,'hi'),
(437,'govt_technical','ref-example','example',3,'Numerical (JE style)',$j${"answer":"3","question":"शीतलन प्रभाव 300 kJ है और कार्य इनपुट 100 kJ है। COP कितना है?","solution":"COP = 300 / 100 = 3"}$j$::jsonb,'hi'),
(437,'govt_basic','ref-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"रेफ्रिजरेटर में ठंडक किस भाग से मिलती है?","answer":0,"options":["इवैपोरेटर","कंप्रेसर","कंडेन्सर","मोटर"],"explanation":"इवैपोरेटर में रेफ्रिजरेंट वाष्पित होकर अंदर की ऊष्मा सोखता है।"},{"q":"दाब बढ़ाने वाला भाग कौन सा है?","answer":0,"options":["कंप्रेसर","इवैपोरेटर","एक्सपैंशन वाल्व","पंखा"],"explanation":"कंप्रेसर रेफ्रिजरेंट का दाब बढ़ाता है।"}]}$j$::jsonb,'hi'),
(437,'govt_technical','ref-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"वाष्प-संपीड़न चक्र में दाब बढ़ाने वाला भाग कौन सा है?","answer":1,"options":["कंडेन्सर","कंप्रेसर","इवैपोरेटर","एक्सपैंशन वाल्व"],"explanation":"कंप्रेसर रेफ्रिजरेंट का दाब और तापमान बढ़ाता है।"},{"q":"आधुनिक रेफ्रिजरेंट का एक उदाहरण कौन सा है?","answer":0,"options":["R-134a","CO","O₃","N₂O₅"],"explanation":"R-134a एक प्रचलित HFC रेफ्रिजरेंट है।"}]}$j$::jsonb,'hi'),
(437,null,'ref-diagram','svg',5,'वाष्प-संपीड़न चक्र',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='30' y='20' width='70' height='30' fill='#60a5fa' rx='4'/><text x='65' y='40' text-anchor='middle' fill='#0f172a' font-size='11'>कंप्रेसर</text><rect x='200' y='20' width='70' height='30' fill='#60a5fa' rx='4'/><text x='235' y='40' text-anchor='middle' fill='#0f172a' font-size='11'>कंडेन्सर</text><rect x='200' y='75' width='70' height='30' fill='#14b8a6' rx='4'/><text x='235' y='95' text-anchor='middle' fill='#0f172a' font-size='11'>इवैपोरेटर</text><rect x='30' y='75' width='70' height='30' fill='#f59e0b' rx='4'/><text x='65' y='95' text-anchor='middle' fill='#0f172a' font-size='11'>वाल्व</text></svg>","caption":"रेफ्रिजरेंट चक्र में घूमकर अंदर से ऊष्मा बाहर निकालता है"}$j$::jsonb,'hi'),
-- 438 Steam Boilers, Turbines, Power Plants
(438,'govt_basic','boil-concept','concept',1,'बॉयलर और टरबाइन',$j${"note":"परीक्षा में बिजली बनने का क्रम (बॉयलर, टरबाइन, जनरेटर) पूछा जाता है।","text":"बॉयलर पानी को भाप बनाता है। भाप टरबाइन को घुमाती है, और टरबाइन जनरेटर को चलाकर बिजली बनाता है।"}$j$::jsonb,'hi'),
(438,'govt_technical','boil-concept','concept',1,'भाप बॉयलर और टरबाइन — SSC JE / RRB JE',$j${"note":"JE में टरबाइन के प्रकार impulse और reaction अक्सर पूछे जाते हैं।","text":"बॉयलर ईंधन की ऊष्मा से पानी को भाप में बदलता है। भाप टरबाइन में ऊष्मीय ऊर्जा यांत्रिक ऊर्जा बनती है, जिससे जनरेटर बिजली बनाता है। आदर्श चक्र रैंकिन (Rankine) चक्र है।"}$j$::jsonb,'hi'),
(438,'govt_basic','boil-formula','formula',2,'तापीय दक्षता',$j${"formula":"η = W_net / Q_in","explanation":"η = दक्षता, W_net = उपयोगी कार्य, Q_in = दी गई ऊष्मा"}$j$::jsonb,'hi'),
(438,'govt_technical','boil-formula','formula',2,'तापीय दक्षता',$j${"formula":"η = W_net / Q_in","explanation":"η = तापीय दक्षता, W_net = शुद्ध कार्य (kJ), Q_in = दी गई ऊष्मा (kJ)"}$j$::jsonb,'hi'),
(438,'govt_basic','boil-example','example',3,'उदाहरण',$j${"answer":"20%","question":"दी गई ऊष्मा 500 kJ है और उपयोगी कार्य 100 kJ है। दक्षता कितनी है?","solution":"η = 100 / 500 = 0.2"}$j$::jsonb,'hi'),
(438,'govt_technical','boil-example','example',3,'Numerical (JE style)',$j${"answer":"30%","question":"शुद्ध कार्य 300 kJ है और दी गई ऊष्मा 1000 kJ है। तापीय दक्षता कितनी है?","solution":"η = 300 / 1000 = 0.3"}$j$::jsonb,'hi'),
(438,'govt_basic','boil-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"बिजली बनाने में भाप सबसे पहले किसे घुमाती है?","answer":0,"options":["टरबाइन","जनरेटर","पंप","पंखा"],"explanation":"भाप पहले टरबाइन को घुमाती है, फिर टरबाइन जनरेटर को।"},{"q":"पानी को भाप बनाने वाला उपकरण कौन सा है?","answer":0,"options":["बॉयलर","कंडेन्सर","जनरेटर","रेडिएटर"],"explanation":"बॉयलर पानी को गर्म करके भाप बनाता है।"}]}$j$::jsonb,'hi'),
(438,'govt_technical','boil-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"बॉयलर में पानी को भाप बनाने के लिए क्या दिया जाता है?","answer":1,"options":["विद्युत","ऊष्मा (ईंधन से)","चुंबकत्व","ध्वनि"],"explanation":"बॉयलर में ईंधन जलाकर मिली ऊष्मा से पानी भाप बनता है।"},{"q":"भाप टरबाइन किस प्रकार की मशीन है?","answer":0,"options":["ऊष्मीय से यांत्रिक ऊर्जा बदलने वाली","यांत्रिक से विद्युत","ध्वनि से ऊर्जा","विद्युत से ऊष्मा"],"explanation":"भाप की ऊष्मीय ऊर्जा टरबाइन में यांत्रिक घूर्णन में बदलती है।"}]}$j$::jsonb,'hi'),
